const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (input) => {
    const str = input.trim();
    let t = 0;
    let found = false;
    for (let i = 0; i < str.length; i++) {
        if (str[i].charCodeAt(0) - 'a'.charCodeAt(0) > t) {
            console.log("NO");
            found = true;
            break;
        }
        if (str[i].charCodeAt(0) - 'a'.charCodeAt(0) === t) {
            t++;
        }
    }
    if (!found) {
        console.log("YES");
    }
    rl.close();
});
```

